using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public static class UiReview {
 static IEnumerable<FrameworkElement> Walk(DependencyObject node){var fe=node as FrameworkElement;if(fe!=null)yield return fe;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var item in Walk(VisualTreeHelper.GetChild(node,i)))yield return item;}
 static string Csv(string value){return "\""+(value??"").Replace("\"","\"\"").Replace("\r"," ").Replace("\n"," ")+"\"";}
 public static void Record(FrameworkElement root,string path,string page){var rows=new List<string>{"Page,Type,Text,Font,Size,X,Y,Width,Height"};var errors=new List<string>();foreach(var e in Walk(root)){if(e.Visibility!=Visibility.Visible||e.ActualWidth<=0||e.ActualHeight<=0)continue;bool hidden=false;DependencyObject parent=e;while(parent!=null&&!object.ReferenceEquals(parent,root)){var ancestor=parent as UIElement;if(ancestor!=null&&ancestor.Visibility!=Visibility.Visible){hidden=true;break;}parent=VisualTreeHelper.GetParent(parent);}if(hidden)continue;var button=e as Button;var text=e as TextBlock;if(button==null&&text==null)continue;string value=button!=null?(button.Content as string??(button.Content is TextBlock?((TextBlock)button.Content).Text:null)):text.Text;if(string.IsNullOrEmpty(value))continue;Point origin;try{origin=e.TranslatePoint(new Point(0,0),root);}catch{continue;}var rect=new Rect(origin,new Size(e.ActualWidth,e.ActualHeight));if(!rect.IntersectsWith(new Rect(0,0,root.ActualWidth,root.ActualHeight)))continue;FontFamily font=button!=null?button.FontFamily:text.FontFamily;double size=button!=null?button.FontSize:text.FontSize;rows.Add(string.Join(",",new[]{Csv(page),Csv(button!=null?"Button":"Text"),Csv(value),Csv(font.Source),size.ToString("0.##",CultureInfo.InvariantCulture),origin.X.ToString("0.##",CultureInfo.InvariantCulture),origin.Y.ToString("0.##",CultureInfo.InvariantCulture),e.ActualWidth.ToString("0.##",CultureInfo.InvariantCulture),e.ActualHeight.ToString("0.##",CultureInfo.InvariantCulture)}));if(button!=null){var ft=new FormattedText(value,CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface(button.FontFamily,button.FontStyle,button.FontWeight,button.FontStretch),button.FontSize,Brushes.Black,1);if(!(button.Content is TextBlock&&((TextBlock)button.Content).TextTrimming==TextTrimming.CharacterEllipsis)&&ft.Width>button.ActualWidth-button.Padding.Left-button.Padding.Right+2)errors.Add("Button label clipped: "+value+" width="+button.ActualWidth);if(ft.Height>button.ActualHeight-button.Padding.Top-button.Padding.Bottom+2)errors.Add("Button height clipped: "+value+" height="+button.ActualHeight);}}
 File.WriteAllLines(path,rows,Encoding.UTF8);if(errors.Count>0){File.WriteAllLines(path+".errors.txt",errors);throw new Exception(page+": "+string.Join("; ",errors));}}
 public static int Run(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true);var m=Program.Fixture("eight");m.Hardware=new HardwareInfo{CpuModel="Intel(R) Xeon(R) Gold 6138 CPU @ 2.00GHz",PhysicalSockets=2,PhysicalCores=64,SystemThreads=128,AvailableThreads=124,MemoryBytes=1024L*1024*1024*512,MemoryModules=new List<MemoryModuleInfo>{new MemoryModuleInfo{Slot="CPU0 DIMM A1",Generation="DDR4",CapacityBytes=32L*1024*1024*1024,ConfiguredSpeed="2666 MT/s",RatedSpeed="2933 MT/s"}},Note="界面排版验证使用模拟硬件信息"};m.Processes[0].User="baiyang";int pages=0;foreach(string theme in Theme.Keys){window.ApplyAppearance(theme);window.SetMetrics(m,false);foreach(string page in new[]{"CPU","GPU","内存"}){window.SwitchView(page);foreach(int width in new[]{760,1200}){int dpi=theme=="graphite"?192:120;string stem=theme+"-"+page+"-"+width;window.RenderImage(Path.Combine(folder,stem+".png"),width,width==760?560:900,dpi);Record(window.Root,Path.Combine(folder,stem+".csv"),stem);if(window.Audit().Count>0)throw new Exception(string.Join(";",window.Audit()));pages++;}window.Scroll.ScrollToBottom();string detail=theme+"-"+page+"-detail";window.RenderImage(Path.Combine(folder,detail+".png"),1200,900,120);Record(window.Root,Path.Combine(folder,detail+".csv"),detail);pages++;}var editor=new SettingsWindow(window.CompactOptions.Copy(),true);foreach(int width in new[]{740,860}){string stem=theme+"-settings-"+width;editor.RenderImage(Path.Combine(folder,stem+".png"),width,760,120);var boxes=Walk(editor.Root).OfType<TextBox>().Where(x=>x.ActualWidth>0).ToArray();if(boxes.Length<5||boxes.Any(x=>x.ActualWidth<120))throw new Exception("Settings connection fields collapsed");Record(editor.Root,Path.Combine(folder,stem+".csv"),stem);pages++;}editor.Close();}window.Exit();File.WriteAllText(Path.Combine(folder,"ui-review-results.txt"),"LAYOUT_AND_FONT_INVENTORIES="+pages+"\nBUTTON_LABEL_BOUNDS=PASS\nGPU_OVERLAP_AND_TOOLBAR_GEOMETRY=PASS\nNOTE=Fixtures are synthetic, viewport intentionally clips scrollable content. Visual review remains required.\n");return 0;}
}
